pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, uint256 v, uint16 n) public {
        uint16 len = uint16(bound(n, 1, 10));

        Reverter r = new Reverter();
        address[] memory tos = new address[](len);
        for (uint16 i = 0; i < len; i++) {
            tos[i] = address(r);
        }

        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
